import numpy as np

def select_next_node(current_node, depot, unvisited_nodes, rest_capacity, demands, distance_matrix):
    """Return an int from unvisited_nodes (or 0 to return to depot early when current_node != 0)."""
    if len(unvisited_nodes) == 0:
        return int(depot)

    # Global scale for scale-invariant normalization
    mean_d0 = float(np.mean(distance_matrix[depot, 1:]))
    if not np.isfinite(mean_d0) or mean_d0 <= 0.0:
        mean_d0 = 1.0

    d0_next = distance_matrix[depot, unvisited_nodes]
    d_cur_next = distance_matrix[current_node, unvisited_nodes]
    savings = (d0_next - d_cur_next) / mean_d0

    dem = demands[unvisited_nodes]
    rest = float(rest_capacity)

    # Capacity-fill regime switch: when capacity is scarce, prefer larger demands
    # that still fit; otherwise blend savings with a mild fill term.
    fill_ratio = dem / max(rest, 1e-12)
    fill_term = 0.25 * fill_ratio

    # Blend: savings dominate in normal regime; fill term grows as rest shrinks.
    if rest < 0.35 * mean_d0:
        fill_term = 1.0 * fill_ratio

    score = savings + fill_term

    # Voluntary early return when capacity is nearly exhausted or the best move is a detour
    if current_node != depot:
        nearest_d = float(np.min(distance_matrix[current_node, unvisited_nodes]))
        best_score = float(np.max(score))
        if rest < 0.15 * mean_d0 and best_score < 0.5 * (nearest_d / mean_d0):
            return int(depot)
        if best_score < 0.0 and rest < 0.30 * mean_d0:
            return int(depot)

    idx = int(np.argmax(score))
    return int(unvisited_nodes[idx])
